window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-bbd59c7d059bd87c"]={"versions": [{"id": "FIG-bbd59c7d059bd87c", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Aktivitätsdiagramm (Sub-Aktivität / Funktionsablauf eines Teilalgorithmus).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der normativen Berechnungslogik zur Einbindung der transmissionsspezifischen Data-ID in die CRC-Prüfsumme (<code>Compute CRC - Data ID</code>) gemäß [PRS_E2E_01254] im AUTOSAR E2E-Profil 22 (End-to-End Communication Protection Protocol).</li>\n<li><strong>Architektur-Einordnung:</strong> Verortet im E2E-Library- bzw. E2E-Transformer-Stack (Classic Platform: System Services / Library <code>E2E</code>; Adaptive Platform: <code>ara::com</code> E2E-Schicht). Der Teilschritt ist sowohl auf Senderseite (<code>E2E_P22Protect()</code>) als auch auf Empfängerseite (<code>E2E_P22Check()</code>) identisch verankert, um kryptografisch bzw. informationstheoretisch sicherzustellen, dass vertauschte, maskierte oder falsch adressierte PDUs (Masquerading / Insertion / Addressing Errors) erkannt werden.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aufrufende Kontexte (Invocations):</strong></li>\n<li><code>E2E_P22Protect()</code>: Senderseitige Schutzfunktion zur PDU-Absicherung vor der Serialisierung/Übertragung.</li>\n<li><code>E2E_P22Check()</code>: Empfängerseitige Verifikationsfunktion zur Integritäts- und Konsistenzprüfung empfangener PDUs.</li>\n<li><strong>Zustands- & Konfigurationsstrukturen:</strong></li>\n<li><code>State</code> (<code>E2E_P22ProtectStateType</code> bzw. <code>E2E_P22CheckStateType</code>): Enthält den aktuellen Sequenzzähler <code>State-&gt;Counter</code> (Wertebereich typischerweise 0..15).</li>\n<li><code>Config</code> (<code>E2E_P22ConfigType</code>): Enthält das Array <code>DataIDList</code> (Konfigurationsvektor von 16 8-Bit-Data-IDs: <code>uint8 DataIDList[16]</code>), parametriert über die BSW-/System-Konfiguration.</li>\n<li><strong>Verwendete BSW-Schnittstelle:</strong></li>\n<li><code>Crc_CalculateCRC8H2F(...)</code> aus der AUTOSAR BSW-Bibliothek <code>Crc</code> (Polynom 0x2F / Koopman-Notation, 8-Bit-CRC nach Bauer/H2F).</li>\n<li><strong>Schnittstellenparameter:</strong></li>\n<li><code>Crc_DataPtr</code>: Zeiger auf das zu hashende Byte <code>&amp;Config-&gt;DataIDList[Counter]</code>.</li>\n<li><code>Crc_Length</code>: <code>1</code> (exakt 1 Byte Nutzdatenlänge für den Data-ID-List-Eintrag).</li>\n<li><code>Crc_StartValue8</code>: <code>ComputedCRC</code> (der aus dem vorherigen Schritt über die PDU-Payload bereits berechnete Zwischenwert).</li>\n<li><code>Crc_isFirstCall</code>: <code>FALSE</code> (Kettenberechnung; verhindert Neuinitialisierung des Algorithmus mit dem Generator-Startwert).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung:</strong> Startknoten wird synchron nach Abschluss der Payload-CRC-Berechnung betreten.</li>\n<li><strong>Zähler-Auswertung:</strong> Der lokale Parameter <code>Counter</code> wird deterministisch aus <code>State-&gt;Counter</code> übernommen.</li>\n<li><strong>Array-Indizierung & CRC-Aktualisierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zugriff auf die systemspezifische Kennung über <code>Config-&gt;DataIDList[Counter]</code>.</li>\n<li>Synchroner Aufruf von <code>Crc_CalculateCRC8H2F()</code> mit Weiterreichung des bisherigen Zwischenergebnisses <code>ComputedCRC</code> als Startwert.</li>\n<li><code>Crc_isFirstCall: FALSE</code> bewirkt die Fortführung des Polynomdivisions-Zustands ohne erneutes XOR mit dem Initialisierungswert.</li>\n<li>Der Rückgabewert überschreibt <code>ComputedCRC</code> mit dem finalen E2E-Prüfsummenwert.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Terminierung:</strong> Ablauf endet im Aktivitätsendknoten und übergibt die Kontrolle an die Folgeschritte:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei <code>E2E_P22Protect()</code>: Folgeschritt <code>Write CRC</code> ([PRS_E2E_00532]) gefolgt von <code>Increment Counter</code> ([PRS_E2E_00533]).</li>\n<li>Bei <code>E2E_P22Check()</code>: Folgeschritt <code>Verify CRC</code> (Abgleich empfangene CRC vs. <code>ComputedCRC</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Array-Grenzen & Konfiguration:</strong> Entwickler müssen sicherstellen, dass <code>Config-&gt;DataIDList</code> vollständig auf den Wertebereich des Zählers ausgelegt ist (16 Einträge bei 4-Bit-Counter). Ein ungültiger oder undefinierter Zählerstand führt zu Out-of-Bounds-Zugriffen auf dem Speicherabbild der BSW-Konfiguration.</li>\n<li><strong>Kettenaufruf-Semantik (<code>Crc_isFirstCall == FALSE</code>):</strong></li>\n<li>Vor Aufruf dieser Sub-Aktivität muss <code>ComputedCRC</code> zwingend den gültigen Zwischenwert der CRC-Berechnung über die zu schützenden Nutzdaten-Bytes enthalten.</li>\n<li>In Treibern oder Hardware-Beschleunigern (HW-CRC-Engines) darf der Akkumulator zwischen Nutzdaten und Data-ID-Schritt nicht zurückgesetzt oder geflusht werden; alternativ muss der Registerstand vor dem Data-ID-Schritt in Software restauriert werden können.</li>\n<li><strong>ASIL-D / ISO 26262 Determinismus:</strong> Die Zuordnung <code>DataIDList[Counter]</code> verhindert Replay- und Masquerade-Angriffe dynamisch pro Sendezyklus. Sender und Empfänger müssen zwingend dieselbe statische <code>DataIDList</code>-Tabelle konfiguriert haben; Konfigurationsdrift führt sofort zu <code>E2E_E_WRONGCRC</code>.</li>\n</ul>"}, {"id": "FIG-a45c8f5949fbc525", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Aktivitätsdiagramm (Sub-Aktivität / Funktionsablauf eines Teilalgorithmus).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der normativen Berechnungslogik zur Einbindung der transmissionsspezifischen Data-ID in die CRC-Prüfsumme (<code>Compute CRC - Data ID</code>) gemäß [PRS_E2E_01254] im AUTOSAR E2E-Profil 22 (End-to-End Communication Protection Protocol).</li>\n<li><strong>Architektur-Einordnung:</strong> Verortet im E2E-Library- bzw. E2E-Transformer-Stack (Classic Platform: System Services / Library <code>E2E</code>; Adaptive Platform: <code>ara::com</code> E2E-Schicht). Der Teilschritt ist sowohl auf Senderseite (<code>E2E_P22Protect()</code>) als auch auf Empfängerseite (<code>E2E_P22Check()</code>) identisch verankert, um kryptografisch bzw. informationstheoretisch sicherzustellen, dass vertauschte, maskierte oder falsch adressierte PDUs (Masquerading / Insertion / Addressing Errors) erkannt werden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aufrufende Kontexte (Invocations):</strong></li>\n<li><code>E2E_P22Protect()</code>: Senderseitige Schutzfunktion zur PDU-Absicherung vor der Serialisierung/Übertragung.</li>\n<li><code>E2E_P22Check()</code>: Empfängerseitige Verifikationsfunktion zur Integritäts- und Konsistenzprüfung empfangener PDUs.</li>\n<li><strong>Zustands- & Konfigurationsstrukturen:</strong></li>\n<li><code>State</code> (<code>E2E_P22ProtectStateType</code> bzw. <code>E2E_P22CheckStateType</code>): Enthält den aktuellen Sequenzzähler <code>State-&gt;Counter</code> (Wertebereich typischerweise 0..15).</li>\n<li><code>Config</code> (<code>E2E_P22ConfigType</code>): Enthält das Array <code>DataIDList</code> (Konfigurationsvektor von 16 8-Bit-Data-IDs: <code>uint8 DataIDList[16]</code>), parametriert über die BSW-/System-Konfiguration.</li>\n<li><strong>Verwendete BSW-Schnittstelle:</strong></li>\n<li><code>Crc_CalculateCRC8H2F(...)</code> aus der AUTOSAR BSW-Bibliothek <code>Crc</code> (Polynom 0x2F / Koopman-Notation, 8-Bit-CRC nach Bauer/H2F).</li>\n<li><strong>Schnittstellenparameter:</strong></li>\n<li><code>Crc_DataPtr</code>: Zeiger auf das zu hashende Byte <code>&amp;Config-&gt;DataIDList[Counter]</code>.</li>\n<li><code>Crc_Length</code>: <code>1</code> (exakt 1 Byte Nutzdatenlänge für den Data-ID-List-Eintrag).</li>\n<li><code>Crc_StartValue8</code>: <code>ComputedCRC</code> (der aus dem vorherigen Schritt über die PDU-Payload bereits berechnete Zwischenwert).</li>\n<li><code>Crc_isFirstCall</code>: <code>FALSE</code> (Kettenberechnung; verhindert Neuinitialisierung des Algorithmus mit dem Generator-Startwert).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung:</strong> Startknoten wird synchron nach Abschluss der Payload-CRC-Berechnung betreten.</li>\n<li><strong>Zähler-Auswertung:</strong> Der lokale Parameter <code>Counter</code> wird deterministisch aus <code>State-&gt;Counter</code> übernommen.</li>\n<li><strong>Array-Indizierung & CRC-Aktualisierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zugriff auf die systemspezifische Kennung über <code>Config-&gt;DataIDList[Counter]</code>.</li>\n<li>Synchroner Aufruf von <code>Crc_CalculateCRC8H2F()</code> mit Weiterreichung des bisherigen Zwischenergebnisses <code>ComputedCRC</code> als Startwert.</li>\n<li><code>Crc_isFirstCall: FALSE</code> bewirkt die Fortführung des Polynomdivisions-Zustands ohne erneutes XOR mit dem Initialisierungswert.</li>\n<li>Der Rückgabewert überschreibt <code>ComputedCRC</code> mit dem finalen E2E-Prüfsummenwert.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Terminierung:</strong> Ablauf endet im Aktivitätsendknoten und übergibt die Kontrolle an die Folgeschritte:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei <code>E2E_P22Protect()</code>: Folgeschritt <code>Write CRC</code> ([PRS_E2E_00532]) gefolgt von <code>Increment Counter</code> ([PRS_E2E_00533]).</li>\n<li>Bei <code>E2E_P22Check()</code>: Folgeschritt <code>Verify CRC</code> (Abgleich empfangene CRC vs. <code>ComputedCRC</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Array-Grenzen & Konfiguration:</strong> Entwickler müssen sicherstellen, dass <code>Config-&gt;DataIDList</code> vollständig auf den Wertebereich des Zählers ausgelegt ist (16 Einträge bei 4-Bit-Counter). Ein ungültiger oder undefinierter Zählerstand führt zu Out-of-Bounds-Zugriffen auf dem Speicherabbild der BSW-Konfiguration.</li>\n<li><strong>Kettenaufruf-Semantik (<code>Crc_isFirstCall == FALSE</code>):</strong></li>\n<li>Vor Aufruf dieser Sub-Aktivität muss <code>ComputedCRC</code> zwingend den gültigen Zwischenwert der CRC-Berechnung über die zu schützenden Nutzdaten-Bytes enthalten.</li>\n<li>In Treibern oder Hardware-Beschleunigern (HW-CRC-Engines) darf der Akkumulator zwischen Nutzdaten und Data-ID-Schritt nicht zurückgesetzt oder geflusht werden; alternativ muss der Registerstand vor dem Data-ID-Schritt in Software restauriert werden können.</li>\n<li><strong>ASIL-D / ISO 26262 Determinismus:</strong> Die Zuordnung <code>DataIDList[Counter]</code> verhindert Replay- und Masquerade-Angriffe dynamisch pro Sendezyklus. Sender und Empfänger müssen zwingend dieselbe statische <code>DataIDList</code>-Tabelle konfiguriert haben; Konfigurationsdrift führt sofort zu <code>E2E_E_WRONGCRC</code>.</li>\n</ul>"}], "trans": [{"from": "FIG-bbd59c7d059bd87c", "to": "FIG-a45c8f5949fbc525", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
